import React from "react";

function formatAuthors(authors) {
  return authors
    .map((author) => `${author.name}${author.equal ? "*" : ""}`)
    .join(", ");
}

export default function PublicationCard({ publication }) {
  const { title, venue, authors, links, description, image } = publication;

  return (
    <article className="paper-card grid grid-cols-1 gap-6 rounded-xl border border-transparent p-4 sm:grid-cols-[180px_minmax(0,1fr)]">
      <div>
        {image ? (
          <img
            src={image}
            alt={title}
            className="aspect-[16/10] w-full rounded-md border border-neutral-200 bg-white object-contain p-2"
          />
        ) : (
          <div className="flex aspect-[16/10] w-full items-center justify-center rounded-md border border-neutral-200 bg-neutral-50 text-sm text-black">
            Image coming soon
          </div>
        )}
      </div>

      <div className="flex flex-col gap-1">
        <h3 className="text-lg font-medium leading-snug text-black sm:text-xl">
          {title}
        </h3>

        <p className="whitespace-nowrap text-sm leading-6 text-black sm:text-sm">
          {formatAuthors(authors)}
        </p>

        <p className="text-sm leading-6 text-black sm:text-sm">{venue}</p>

        {links && links.length > 0 && (
          <div className="flex flex-wrap items-center gap-x-3 text-sm leading-6 text-black sm:text-sm">
            {links.map((link, index) => (
              <React.Fragment key={link.label}>
                <a
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-blue-600 transition-colors hover:text-orange-500"
                >
                  {link.label}
                </a>
                {index < links.length - 1 && (
                  <span className="text-black">/</span>
                )}
              </React.Fragment>
            ))}
          </div>
        )}

        {description && (
          <p className="mt-3 text-sm leading-6 text-black sm:text-sm">
            {description}
          </p>
        )}
      </div>
    </article>
  );
}
